import re,os,json,collections
RT='rt'
cons={r['file'] for r in map(json.loads,open('pack74/GOAUDIT3.jsonl')) if r['cls']=='CONSTRUCT'}
def imports(f):
    try: t=open(os.path.join(RT,f),encoding='utf-8',errors='replace').read()
    except: return set()
    s=set()
    for m in re.finditer(r'^\s*(?:from\s+([\w\.]+)\s+import|import\s+([\w\., ]+))',t,re.M):
        for g in m.groups():
            if g:
                for nm in g.split(','):
                    nm=nm.strip().split(' as ')[0].split('.')[0]
                    if os.path.exists(os.path.join(RT,nm+'.py')): s.add(nm+'.py')
    return s
# transitive closure from the two Deliverable-1 gates
def closure(seed):
    seen=set(); stack=list(seed)
    while stack:
        f=stack.pop()
        if f in seen: continue
        seen.add(f)
        stack+= [x for x in imports(f) if x not in seen]
    return seen
for seed in (['gate86.py'],['nlchain.py'],['nlcfg.py']):
    cl=closure(seed)
    bad=sorted(cl&cons)
    print("%-14s deps=%-3d CONSTRUCT-side in closure: %d %s"%(seed[0],len(cl),len(bad),bad if bad else ''))
